  if (h < 0.58) return vec3(1.0, 0.60, 0.28);          // incandescent / warm LED
  if (h < 0.84) return vec3(1.0, 0.78, 0.52);          // warm white
  if (h < 0.97) return vec3(0.78, 0.88, 1.0);          // fluorescent tube (every other Chinese kitchen)
